SELECT 'all 15 creatures are in' AS assertion, count(*) AS got, 15 AS want
  FROM creatures WHERE slug IN ('doppleganger', 'hounds', 'hound-masters', 'hunters', 'ashmedai', 'namtar', 'waste-coyote', 'snake-bird', 'lizard-king', 'night-princes', 'master-vampire', 'secondary-vampire', 'wild-vampires', 'guardians', 'wampyr');
SELECT 'and their 30 attacks' AS assertion, count(*) AS got, 30 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('doppleganger', 'hounds', 'hound-masters', 'hunters', 'ashmedai', 'namtar', 'waste-coyote', 'snake-bird', 'lizard-king', 'night-princes', 'master-vampire', 'secondary-vampire', 'wild-vampires', 'guardians', 'wampyr');

